      <span>PixelShelf</span>
    </a>
  </header>

  <main id="main">
    <article class="preview-card" aria-labelledby="page-title">
      <div class="image-panel">
        <div class="image-frame">
          <svg role="img" aria-labelledby="preview-title preview-desc" viewBox="0 0 520 390" xmlns="http://www.w3.org/2000/svg">
            <title id="preview-title">Abstract mountain sunrise image preview</title>
            <desc id="preview-desc">A stylized image with mountains, a sun, and a gradient sky.</desc>
            <rect width="520" height="390" rx="34" fill="currentColor"></rect>
            <circle cx="385" cy="105" r="54" fill="#fef3c7"></circle>
            <path d="M0 300 135 170l95 90 74-68 216 164v34H0z" fill="#1d4ed8"></path>
            <path d="M0 334 165 210l118 112 91-88 146 112v44H0z" fill="#0f766e"></path>
            <path d="M135 170 92 211l50-16 35 28zM304 192l-40 37 44-13 30 22z" fill="#ffffff"></path>
          </svg>
        </div>
      </div>

      <div class="content-panel">
        <div>
          <p class="eyebrow">Image preview</p>
          <h1 id="page-title">Golden Ridge</h1>
          <p class="description">A warm abstract landscape saved to your personal library. Review the details below before keeping or removing it.</p>
          <ul class="metadata" aria-label="Image details">
            <li>Uploaded today</li>
            <li>PNG</li>
            <li>2.4 MB</li>
          </ul>
        </div>

        <div>
          <div class="actions">
            <button class="secondary-button" type="button">Download</button>
            <button class="trigger" type="button" aria-haspopup="dialog">Delete image</button>
          </div>
          <p class="status" aria-live="polite"></p>
        </div>
      </div>
    </article>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form method="dialog" class="dialog-content">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">This will permanently remove “Golden Ridge” from your library. This action cannot be undone.</p>
      <div class="dialog-actions">
        <button class="secondary-button" value="cancel" type="submit">Cancel</button>
        <button class="danger-button" value="delete" type="submit">Delete image</button>
      </div>
    </form>
  </dialog>

  <script>
    const trigger = document.querySelector(".trigger");
    const dialog = document.querySelector("#delete-dialog");
    const statusMessage = document.querySelector(".status");
    let previouslyFocusedElement = null;

    trigger.addEventListener("click", () => {
      previouslyFocusedElement = document.activeElement;
      dialog.showModal();
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue === "delete") {
        statusMessage.textContent = "Golden Ridge was deleted from your library.";
      }

      if (previouslyFocusedElement && typeof previouslyFocusedElement.focus === "function") {
        previouslyFocusedElement.focus();
      }
    });

    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) {
        dialog.close("cancel");
      }
    });
  </script>
